// Brand color constants — used in Recharts SVG (CSS variables don't resolve in SVG context)
const BRAND_PRIMARY = '#5B5FC7';

import { useMemo } from "react";
import { Link } from "react-router-dom";
import {
  ScanLine,
  Target,
  AlertTriangle,
  Zap,
  ArrowRight,
  ArrowUpRight,
  TrendingUp,
  Globe,
  AlertCircle,
  Sparkles,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  ResponsiveContainer,
  Cell,
  Tooltip,
} from "recharts";
import { KpiCard } from "@/components/shared/KpiCard";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { UrlInput } from "@/components/shared/UrlInput";
import { PageTransition } from "@/components/shared/PageTransition";
import { EmptyState } from "@/components/shared/EmptyState";
import { ScoreHealthHero } from "@/components/dashboard/ScoreHealthHero";
import { ActionItemsStrip } from "@/components/dashboard/ActionItemsStrip";
import { MilestoneTracker } from "@/components/dashboard/MilestoneTracker";
import { ScoreTrendChart } from "@/components/dashboard/ScoreTrendChart";
import {
  getScoreColor,
  formatRelativeDate,
  getSeverityColor,
  getEffortColor,
  getEffortLabel,
} from "@/lib/score-utils";
import { useAuth } from "@/contexts/AuthContext";
import { useDashboardStats } from "@/hooks/use-dashboard-stats";
import { ChartErrorBoundary } from "@/components/shared/ChartErrorBoundary";
import { cn } from "@/lib/utils";
import type { Finding } from "@/types";

// ── Status badge helper ─────────────────────────────────────────

function getStatusBadge(status: string) {
  if (status === "completed") {
    return (
      <Badge
        variant="outline"
        className="border-emerald-200/80 bg-emerald-50/50 text-emerald-700 text-xs font-medium"
      >
        Completed
      </Badge>
    );
  }
  if (status === "analyzing") {
    return (
      <Badge
        variant="outline"
        className="border-amber-200/80 bg-amber-50/50 text-amber-700 text-xs font-medium animate-pulse"
      >
        Analyzing
      </Badge>
    );
  }
  return (
    <Badge variant="outline" className="text-xs">
      {status}
    </Badge>
  );
}

// ── Pillar label map ────────────────────────────────────────────

const PILLAR_LABELS: Record<string, string> = {
  value_proposition: "Value Proposition",
  cta_effectiveness: "CTA Effectiveness",
  trust_signals: "Trust Signals",
  visual_hierarchy: "Visual Hierarchy",
  mobile_experience: "Mobile Experience",
  content_copy: "Content & Copy",
  page_performance: "Page Performance",
};

// ── Dashboard Skeleton ──────────────────────────────────────────

function DashboardSkeleton() {
  return (
    <div className="space-y-6">
      {/* Hero */}
      <Skeleton className="h-[140px] rounded-2xl" />
      {/* KPI row */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-5">
        {[1, 2, 3, 4, 5].map((i) => (
          <Skeleton key={i} className="h-[100px] rounded-lg" />
        ))}
      </div>
      {/* Trend + Milestone */}
      <div className="grid grid-cols-1 gap-5 lg:grid-cols-3">
        <Skeleton className="h-[300px] lg:col-span-2 rounded-lg" />
        <Skeleton className="h-[300px] rounded-lg" />
      </div>
      {/* Recent scans */}
      <Skeleton className="h-56 rounded-lg" />
    </div>
  );
}

// ── Component ───────────────────────────────────────────────────

const Dashboard = () => {
  const { profile } = useAuth();
  const { data, isLoading } = useDashboardStats();

  const recentScans = data?.recentScans ?? [];
  const completedScans = useMemo(
    () => recentScans.filter((s) => s.status === "completed"),
    [recentScans]
  );

  if (isLoading) {
    return (
      <PageTransition>
        <DashboardSkeleton />
      </PageTransition>
    );
  }

  const stats = data?.stats;
  const scoreDistribution = data?.scoreDistribution ?? [];
  const topQuickWins = data?.topQuickWins ?? [];
  const latestScanId = data?.latestScanId ?? null;
  const hasScans = completedScans.length > 0;

  const firstName = profile?.full_name?.split(" ")[0] ?? "there";
  const scansUsed = profile?.scans_used ?? 0;
  const scanLimit = profile?.scan_limit ?? 3;
  const scanUsagePercent = Math.round((scansUsed / scanLimit) * 100);
  const atLimit = scansUsed >= scanLimit;

  // New fields
  const bestScore = data?.best_score ?? 0;
  const scansThisWeek = data?.scans_this_week ?? 0;
  const scoreTrendData = data?.score_trend_data ?? [];
  const criticalActionItems = data?.critical_action_items ?? [];

  // Score delta vs previous week point in trend data
  const scoreChange = (() => {
    if (scoreTrendData.length < 2) return 0;
    const last = scoreTrendData[scoreTrendData.length - 1].score;
    const prev = scoreTrendData[scoreTrendData.length - 2].score;
    return last - prev;
  })();

  if (!hasScans) {
    return (
      <PageTransition>
        <div className="space-y-6">
          <ScoreHealthHero
            avgScore={0}
            scansThisWeek={0}
            firstName={firstName}
            hasScans={false}
          />
          <Card className="border-dashed border-border/60 shadow-none">
            <CardContent className="py-10">
              <EmptyState
                icon={ScanLine}
                title="No scans yet"
                description="Paste any URL below to get a detailed CRO audit with actionable recommendations in under 30 seconds."
                className="py-0"
              />
              <div className="mx-auto mt-5 max-w-lg">
                <UrlInput buttonText="Run First Scan" />
              </div>
            </CardContent>
          </Card>
        </div>
      </PageTransition>
    );
  }

  return (
    <PageTransition>
      <div className="space-y-6">
        {/* ── 1. ScoreHealthHero ────────────────────────────────── */}
        <ScoreHealthHero
          avgScore={stats?.avg_score ?? 0}
          scansThisWeek={scansThisWeek}
          firstName={firstName}
          hasScans={hasScans}
        />

        {/* ── 2. ActionItemsStrip (only when items exist) ───────── */}
        {criticalActionItems.length > 0 && (
          <ActionItemsStrip items={criticalActionItems} />
        )}

        {/* ── 3. KPI Cards — 5 cards including Score Change ─────── */}
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-5">
          <div className="animate-fade-in" style={{ animationDelay: "0ms" }}>
            <KpiCard
              title="Total Scans"
              value={stats?.total_scans ?? 0}
              icon={ScanLine}
              trend={stats?.scans_trend}
              trendLabel="vs last month"
              iconBg="bg-primary/8"
              iconColor="text-primary"
            />
          </div>
          <div
            className="animate-fade-in"
            style={{ animationDelay: "60ms", animationFillMode: "both" }}
          >
            <KpiCard
              title="Avg. CRO Score"
              value={stats?.avg_score ?? 0}
              suffix="/100"
              icon={Target}
              trend={stats?.score_trend}
              trendLabel="pts this month"
              iconBg="bg-amber-500/8"
              iconColor="text-amber-500"
              valueColor={getScoreColor(stats?.avg_score ?? 0)}
            />
          </div>
          <div
            className="animate-fade-in"
            style={{ animationDelay: "120ms", animationFillMode: "both" }}
          >
            <KpiCard
              title="Issues Found"
              value={stats?.total_issues ?? 0}
              icon={AlertTriangle}
              iconBg="bg-red-500/8"
              iconColor="text-red-500"
            />
          </div>
          <div
            className="animate-fade-in"
            style={{ animationDelay: "180ms", animationFillMode: "both" }}
          >
            <KpiCard
              title="Quick Wins"
              value={stats?.quick_wins ?? 0}
              icon={Zap}
              iconBg="bg-emerald-500/8"
              iconColor="text-emerald-500"
            />
          </div>
          <div
            className="animate-fade-in"
            style={{ animationDelay: "240ms", animationFillMode: "both" }}
          >
            <KpiCard
              title="Score Change"
              value={Math.abs(scoreChange)}
              prefix={scoreChange >= 0 ? "+" : "-"}
              suffix=" pts"
              icon={TrendingUp}
              iconBg="bg-violet-500/8"
              iconColor="text-violet-500"
              valueColor={scoreChange >= 0 ? "text-emerald-500" : "text-red-500"}
            />
          </div>
        </div>

        {/* ── 4. Score Trend (2/3) + Milestone Tracker (1/3) ────── */}
        <div className="grid grid-cols-1 gap-5 lg:grid-cols-3">
          <div className="lg:col-span-2">
            <ScoreTrendChart data={scoreTrendData} />
          </div>
          <MilestoneTracker
            totalScans={stats?.total_scans ?? 0}
            bestScore={bestScore}
          />
        </div>

        {/* ── 5. Recent Scans + right sidebar ──────────────────── */}
        <div className="grid grid-cols-1 gap-5 lg:grid-cols-3">
          {/* Recent Scans table (2 cols) */}
          <Card className="border-border/50 shadow-soft hover:shadow-soft-md transition-shadow lg:col-span-2">
            <CardHeader className="flex flex-row items-center justify-between pb-3">
              <CardTitle className="text-sm font-medium">Recent Scans</CardTitle>
              <Button
                variant="ghost"
                size="sm"
                asChild
                className="text-xs text-primary hover:text-primary h-7"
              >
                <Link to="/reports">
                  View All
                  <ArrowRight className="ml-1 h-3 w-3" />
                </Link>
              </Button>
            </CardHeader>
            <CardContent className="px-0 pb-0">
              <div className="overflow-x-auto scrollbar-thin">
                <Table>
                  <TableHeader>
                    <TableRow className="hover:bg-transparent bg-muted/20">
                      <TableHead className="pl-6">Page</TableHead>
                      <TableHead>Score</TableHead>
                      <TableHead>Issues</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead>When</TableHead>
                      <TableHead className="pr-6 text-right" />
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {completedScans.map((scan) => {
                      let hostname = scan.url;
                      try {
                        hostname = new URL(scan.url).hostname.replace("www.", "");
                      } catch {
                        /* keep raw url */
                      }
                      return (
                        <TableRow
                          key={scan.id}
                          className="group hover:bg-muted/30"
                        >
                          <TableCell className="pl-6">
                            <div className="flex items-center gap-3">
                              <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-muted/50">
                                <Globe className="h-3.5 w-3.5 text-muted-foreground" />
                              </div>
                              <div className="min-w-0">
                                <p className="truncate text-sm font-medium text-foreground max-w-[200px]">
                                  {scan.page_title ?? hostname}
                                </p>
                                <p className="truncate text-xs text-muted-foreground max-w-[200px]">
                                  {hostname}
                                </p>
                              </div>
                            </div>
                          </TableCell>
                          <TableCell>
                            <div className="flex items-center gap-2">
                              <ScoreRing
                                score={scan.overall_score ?? 0}
                                size={28}
                                strokeWidth={3}
                                showLabel={false}
                              />
                              <span
                                className={cn(
                                  "text-sm font-semibold tabular-nums",
                                  getScoreColor(scan.overall_score ?? 0)
                                )}
                              >
                                {scan.overall_score}
                              </span>
                            </div>
                          </TableCell>
                          <TableCell>
                            <span className="text-sm text-muted-foreground tabular-nums">
                              {scan.issues_found}
                              {scan.critical_issues > 0 && (
                                <span className="ml-1 text-red-500 font-medium">
                                  ({scan.critical_issues})
                                </span>
                              )}
                            </span>
                          </TableCell>
                          <TableCell>{getStatusBadge(scan.status)}</TableCell>
                          <TableCell className="text-sm text-muted-foreground">
                            {formatRelativeDate(scan.created_at)}
                          </TableCell>
                          <TableCell className="pr-6 text-right">
                            <Button
                              variant="ghost"
                              size="sm"
                              asChild
                              className="text-xs text-muted-foreground hover:text-primary transition-colors h-7"
                            >
                              <Link to={`/reports/${scan.id}`}>
                                View
                                <ArrowUpRight className="ml-1 h-3 w-3" />
                              </Link>
                            </Button>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </div>
            </CardContent>
          </Card>

          {/* Right sidebar */}
          <div className="space-y-5">
            {/* Quick Scan */}
            <Card className="border-border/40 shadow-soft overflow-hidden relative">
              <div className="absolute top-0 left-0 right-0 h-[2px] bg-gradient-to-r from-primary/80 to-primary" />
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium">Quick Scan</CardTitle>
              </CardHeader>
              <CardContent>
                {atLimit ? (
                  <div className="space-y-3">
                    <div className="pointer-events-none opacity-50">
                      <UrlInput buttonText="Analyze Now" />
                    </div>
                    <div className="flex items-start gap-2.5 rounded-lg border border-amber-200/70 bg-amber-50/60 px-3 py-2.5">
                      <AlertCircle className="mt-0.5 h-4 w-4 shrink-0 text-amber-600" />
                      <div className="min-w-0">
                        <p className="text-xs font-medium text-amber-800">
                          You've used all {scanLimit} scans this month.
                        </p>
                        <Link
                          to="/pricing"
                          className="mt-0.5 inline-flex items-center gap-0.5 text-xs font-semibold text-amber-700 hover:underline"
                        >
                          Upgrade to Pro
                          <ArrowRight className="h-3 w-3" />
                        </Link>
                      </div>
                    </div>
                    <Button asChild className="h-10 w-full rounded-lg text-sm font-semibold">
                      <Link to="/pricing">Upgrade Plan</Link>
                    </Button>
                  </div>
                ) : (
                  <>
                    <UrlInput buttonText="Scan" />
                    <div className="mt-3 flex flex-wrap gap-1.5">
                      {["~30 seconds", "7 pillars", "AI suggestions"].map((tag) => (
                        <span
                          key={tag}
                          className="inline-flex items-center rounded-md border border-border/50 bg-muted/30 px-2 py-0.5 text-xs text-muted-foreground"
                        >
                          {tag}
                        </span>
                      ))}
                    </div>
                  </>
                )}
              </CardContent>
            </Card>

            {/* Scan Usage */}
            <Card className="border-border/40 shadow-soft">
              <CardHeader className="pb-2">
                <div className="flex items-center justify-between">
                  <CardTitle className="text-sm font-medium">Scan Usage</CardTitle>
                  <span className="text-xs text-muted-foreground tabular-nums">
                    {scansUsed}/{scanLimit}
                  </span>
                </div>
              </CardHeader>
              <CardContent className="space-y-2">
                <Progress value={scanUsagePercent} className="h-2" />
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">
                    {scanLimit - scansUsed} scans remaining
                  </span>
                  {scansUsed >= scanLimit - 1 && (
                    <Link
                      to="/pricing"
                      className="text-xs font-medium text-primary hover:underline"
                    >
                      Upgrade
                    </Link>
                  )}
                </div>
              </CardContent>
            </Card>

            {/* Score Distribution */}
            <Card className="border-border/50 shadow-soft">
              <CardHeader className="flex flex-row items-center justify-between pb-1">
                <CardTitle className="text-sm font-medium">Score Distribution</CardTitle>
                <span className="text-xs text-muted-foreground">All scans</span>
              </CardHeader>
              <CardContent>
                <ChartErrorBoundary fallbackHeight={120}>
                  <ResponsiveContainer width="100%" height={120}>
                    <BarChart
                      data={scoreDistribution}
                      barCategoryGap="20%"
                      margin={{ top: 4, right: 0, bottom: 0, left: 0 }}
                    >
                      <XAxis
                        dataKey="range"
                        tick={{ fontSize: 10, fill: "#94A3B8" }}
                        axisLine={false}
                        tickLine={false}
                      />
                      <YAxis hide />
                      <Tooltip
                        contentStyle={{
                          fontSize: 12,
                          borderRadius: 8,
                          border: "1px solid hsl(220 13% 91%)",
                          boxShadow: "0 2px 8px rgba(0,0,0,0.05)",
                        }}
                        formatter={(value: number) => [`${value} scans`, "Count"]}
                      />
                      <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                        {scoreDistribution.map((entry, index) => (
                          <Cell key={index} fill={entry.fill} fillOpacity={0.8} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </ChartErrorBoundary>
              </CardContent>
            </Card>
          </div>
        </div>

        {/* ── Top Quick Wins ───────────────────────────────────── */}
        {topQuickWins.length > 0 && (
          <Card className="border-border/50 shadow-soft">
            <CardHeader className="flex flex-row items-center justify-between pb-3">
              <div className="flex items-center gap-2.5">
                <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-emerald-500/8">
                  <Sparkles className="h-4 w-4 text-emerald-600" />
                </div>
                <div>
                  <CardTitle className="text-sm font-medium">Top Quick Wins</CardTitle>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Highest-impact changes you can make right now
                  </p>
                </div>
              </div>
              {latestScanId && (
                <Button
                  variant="ghost"
                  size="sm"
                  asChild
                  className="text-xs text-primary hover:text-primary h-7"
                >
                  <Link to={`/reports/${latestScanId}`}>
                    Full report
                    <ArrowRight className="ml-1 h-3 w-3" />
                  </Link>
                </Button>
              )}
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 gap-3 md:grid-cols-3">
                {topQuickWins.map((finding: Finding & { pillar: string }) => {
                  const sevColors = getSeverityColor(finding.severity);
                  return (
                    <div
                      key={finding.id}
                      className="group relative rounded-xl border border-border/40 p-4 hover:shadow-soft-md hover:-translate-y-0.5 transition-all duration-200"
                    >
                      <div className="flex items-start justify-between gap-2 mb-2.5">
                        <Badge
                          variant="outline"
                          className={cn(
                            "text-2xs shrink-0",
                            sevColors.bg,
                            sevColors.text,
                            sevColors.border
                          )}
                        >
                          {finding.severity}
                        </Badge>
                        <Badge
                          variant="outline"
                          className={cn(
                            "text-2xs shrink-0",
                            getEffortColor(finding.effort)
                          )}
                        >
                          {getEffortLabel(finding.effort)}
                        </Badge>
                      </div>
                      <h4 className="text-sm font-medium text-foreground leading-snug mb-1.5">
                        {finding.title}
                      </h4>
                      <p className="text-xs text-muted-foreground leading-relaxed line-clamp-2 mb-3">
                        {finding.recommendation}
                      </p>
                      <Separator className="mb-2.5" />
                      <div className="flex items-center justify-between">
                        <div>
                          <span className="text-xs text-muted-foreground">Lift: </span>
                          <span className="text-xs font-medium text-emerald-600">
                            {finding.estimated_lift}
                          </span>
                        </div>
                        <span className="text-2xs text-muted-foreground">
                          {PILLAR_LABELS[finding.pillar] ?? finding.pillar}
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </PageTransition>
  );
};

export default Dashboard;
